self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);const core=['./index.html','./theory.html','./home.css','./styles.css','./app.js','./progress.js','./updates.js','./theme-init.js','./version.json','./manifest.webmanifest','./saek.html','./official_questions.json'];await Promise.allSettled(core.map(x=>cache.add(new Request(x,{cache:'reload'}))));await Promise.allSettled(PARAMEDIC_OFFLINE.map(x=>cache.add(new Request(x,{cache:'reload'}))));await Promise.allSettled(ASSETS.filter(x=>x!=='./'&&!core.includes(x)).map(x=>cache.add(x)));await self.skipWaiting()})()));
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING')self.skipWaiting()});
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if((name.startsWith('ekab-eoppep-official-')||name.startsWith('ekab-spoudi-v'))&&name!==CACHE)await caches.delete(name);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET')return;const url=new URL(req.url);if(url.origin!==self.location.origin)return;
 // Never cache OAuth return documents or URLs containing one-time credentials.
 if(url.pathname.endsWith('/oauth-callback.html')||url.searchParams.has('secret')||url.searchParams.has('userId'))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const resp=await fetch(req,{cache:'no-cache'});if(resp.ok&&url.protocol==='https:'&&req.cache!=='no-store')cache.put(req,resp.clone()).catch(()=>{});return resp}catch(e){const old=await cache.match(req,{ignoreSearch:true});if(old)return old;if(req.mode==='navigate'){const index=await cache.match('./index.html');if(index)return index}return Response.error()}})());
});
